scenarios.push(citations());

function rebase(): Scenario {
  const s = fresh('rebase');
  s.apply([op.insertBlock(para('a', 'alpha')), op.insertBlock(para('b', 'beta')), op.insertBlock(b.heading('h', 1, 'Heading'))]);
  const base = s.snap.revision;
  s.apply([op.setTitle('moved on')]);
  s.apply([op.setTitle('stale title')], { baseRevision: base });
  s.apply([op.updateBlock('a', ver(s, 'a'), content('alpha 2'))], { baseRevision: base }); // no policy
  s.apply([op.updateBlock('a', ver(s, 'a'), content('alpha 2'))], { baseRevision: base, conflictPolicy: 'reject' });
  s.apply([op.updateBlock('a', ver(s, 'a'), content('alpha 2'))], { baseRevision: base, conflictPolicy: 'rebase-safe' });
  s.apply([op.updateBlock('a', ver(s, 'a'), { type: 'heading', level: 2, text: 'type change' })], { baseRevision: base, conflictPolicy: 'rebase-safe' });
  s.apply([op.updateBlock('ghost', 1, content('x'))], { baseRevision: base, conflictPolicy: 'rebase-safe' });
  s.apply([op.updateBlock('a', 1, content('old version'))], { baseRevision: base, conflictPolicy: 'rebase-safe' });
  s.apply([op.replaceText('b', ver(s, 'b'), 'beta', 'BETA')], { baseRevision: base, conflictPolicy: 'rebase-safe' });
  s.apply([op.replaceText('b', ver(s, 'b'), 'beta', 'x')], { baseRevision: base, conflictPolicy: 'rebase-safe' });
  s.apply([op.replaceText('b', ver(s, 'b'), 'BETA', 'again'), op.updateBlock('h', ver(s, 'h'), { type: 'heading', level: 3, text: 'Both' })], { baseRevision: base, conflictPolicy: 'rebase-safe' });
  s.apply([op.replaceText('b', ver(s, 'b'), 'again', 'mixed'), op.setTitle('not rebasable')], { baseRevision: base, conflictPolicy: 'rebase-safe' });
  s.apply([op.setTitle('future')], { baseRevision: s.snap.revision + 1, conflictPolicy: 'rebase-safe' });
  s.apply([op.setTitle('current rebase-safe')], { conflictPolicy: 'rebase-safe' });
  s.apply([op.setTitle('ok reject')], { conflictPolicy: 'reject' });
  s.apply([op.setTitle('bad policy')], { conflictPolicy: 'maybe' as never });
  s.apply([]);
  s.undo(); s.undo();
  return s.done();
}
scenarios.push(rebase());

function idempotency(): Scenario {
  const s = fresh('idempotency');
  const first = s.apply([op.insertBlock(para('a', 'alpha'))]);
  const firstTx = first.input as Transaction;
  s.raw(firstTx); // identical retry of the last success
  s.apply([op.setTitle('second')], { id: 'tx-second' });
  s.raw(firstTx); // an older id: consumed
  s.raw({ id: 'tx-second', actor: agent, baseRevision: s.snap.revision - 1, operations: [op.setTitle('second')] }); // same id, different payload
  s.raw({ id: 'tx-second', actor: agent, baseRevision: s.snap.revision - 1, operations: [op.setTitle('second')] });
  const failing = s.apply([op.updateBlock('a', 99, content('x'))], { id: 'tx-fail' });
  s.raw(failing.input); // a failed id is not consumed
  s.apply([op.insertBlock(para('b', 'beta'))], { id: 'tx-third' });
  s.undo();
  s.raw({ id: 'tx-third', actor: agent, baseRevision: s.snap.revision, operations: [op.insertBlock(para('b2', 'beta2'))] }); // consumed even after undo
  s.apply([op.insertBlock(para('b', 'reuse of the undone id'))]);
  s.raw({ id: 'tx-4', actor: { id: 'a', kind: 'robot' }, baseRevision: 1, operations: [] });
  s.raw('not an object');
  s.raw(null);
  s.raw({});
  s.raw({ id: 'tx-5', actor: agent, baseRevision: -1, operations: [] });
  s.raw({ id: 'tx-6', actor: agent, baseRevision: s.snap.revision, operations: [{ type: 'explode' }] });
  s.raw({ id: 'tx-7', actor: agent, baseRevision: s.snap.revision, operations: [op.setTitle('x')], extra: 1 });
  return s.done();
}
scenarios.push(idempotency());

function history(): Scenario {
  const s = fresh('history');
  s.undo(); s.redo();
  s.apply([op.insertBlock(para('a', 'alpha')), op.insertBlock(para('b', 'beta'))]);
  s.apply([op.updateBlock('a', ver(s, 'a'), content('alpha 2'))]);
  s.apply([op.moveBlock('b', ver(s, 'b'), null, null)]);
  s.apply([op.deleteBlock('a', ver(s, 'a'))]);
  s.undo(s.snap.revision - 1);
  s.undo(s.snap.revision, { id: 'x', kind: 'wizard' } as never);
  s.undo(-1);
  s.undo();
  s.apply([op.insertBlock(para('a', 'cannot reuse a retired id'))]);
  s.undo();
  s.redo();
  s.redo();
  s.undo(); s.undo(); s.undo(); s.undo(); s.undo();
  s.redo(); s.redo();
  s.apply([op.insertBlock(para('c', 'new branch'))]); // clears redo
  s.redo();
  s.undo();
  s.undo();
  s.apply([op.addCitation(citation('c1')), op.insertBlock({ id: 'cited', parentId: null, content: { type: 'paragraph', runs: [{ text: 't', citationId: 'c1' }] }, citationIds: ['c1'] })]);
  s.apply([op.removeCitation('c1')]);
  s.undo();
  s.redo();
  s.undo(); s.undo();
  const limited = fresh('history-limited', { historyLimit: 2 });
  for (let i = 1; i <= 5; i++) limited.apply([op.insertBlock(para(`p${i}`, `paragraph ${i}`))]);
  limited.undo(); limited.undo(); limited.undo(); limited.redo(); limited.redo(); limited.redo();
  const none = fresh('history-off', { historyLimit: 0 });
  none.apply([op.insertBlock(para('p1', 'one'))]); none.undo(); none.apply([op.insertBlock(para('p2', 'two'))]); none.undo(); none.redo();
  const one = fresh('history-one', { historyLimit: 1 });
  one.apply([op.insertBlock(para('p1', 'one'))]); one.apply([op.insertBlock(para('p2', 'two'))]); one.undo(); one.undo(); one.redo();
  scenarios.push(limited.done(), none.done(), one.done());
  return s.done();
}
scenarios.push(history());

function structure(): Scenario {
  // Undo of nested edits: containers, reorders, deletes of subtrees, restored versions.
  const s = fresh('structure');
  s.apply([op.insertBlock(b.section('s1', 'S1')), op.insertBlock(para('a', 'a', 's1')), op.insertBlock(para('b', 'b', 's1')), op.insertBlock(para('c', 'c', 's1')), op.insertBlock(b.section('s2', 'S2'))]);
  s.apply([op.moveBlock('c', ver(s, 'c'), 's1', null)]);
  s.apply([op.moveBlock('b', ver(s, 'b'), 's2')]);
  s.apply([op.deleteBlock('s1', ver(s, 's1'))]);
  s.undo(); s.undo(); s.undo(); s.redo(); s.redo(); s.redo();
  s.apply([op.updateBlock('b', ver(s, 'b'), content('b2'))]);
  s.apply([op.updateBlock('b', ver(s, 'b'), content('b3'))]);
  s.undo(); s.undo(); s.undo();
  s.redo(); s.redo();
  s.apply([op.duplicateBlock('s2', ver(s, 's2'), { s2: 's2c', b: 'bc' })]);
  s.undo();
  s.redo();
  return s.done();
}
scenarios.push(structure());

function clocks(): Scenario {
  const s = fresh('clocks');
  s.apply([op.insertBlock(para('a', 'alpha'))]);
  s.apply([op.setTitle('backwards')], {}, iso(BASE - 60_000));
  s.apply([op.setTitle('garbage clock')], {}, 'yesterday');
  s.apply([op.setTitle('offset clock')], {}, '2026-11-09T09:30:00+02:00');
  s.apply([op.setTitle('millis clock')], {}, '2026-11-09T12:00:00.123Z');
  s.apply([op.setTitle('same instant')], {}, '2026-11-09T12:00:00.123Z');
  s.apply([op.setTitle('earlier millis')], {}, '2026-11-09T12:00:00.122Z');
  s.apply([op.setTitle('leap day')], {}, '2028-02-29T00:00:00Z');
  s.apply([op.setTitle('not a date')], {}, '2029-02-29T00:00:00Z');
  s.apply([op.setTitle('year 9999')], {}, '9999-12-31T23:59:59.999Z');
  s.apply([op.setTitle('after the end of time')], {}, '9999-12-31T23:59:59.998Z');
  s.undo();
  return s.done();
}
scenarios.push(clocks());

function overflow(): Scenario {
  const MAX = Number.MAX_SAFE_INTEGER;
  const doc = createDocument({ id: 'doc-overflow', title: 'Overflow' }, { now: () => iso(BASE) });
  const near = { ...doc, revision: 5, blocks: [
    { id: 'hi', parentId: null, content: content('high'), citationIds: [], version: MAX, createdAt: iso(BASE), updatedAt: iso(BASE) },
    { id: 'lo', parentId: null, content: content('low'), citationIds: [], version: MAX - 1, createdAt: iso(BASE), updatedAt: iso(BASE) },
  ] };
  const s = new Session('overflow', near);
  s.apply([op.updateBlock('hi', MAX, content('x'))]);
  s.apply([op.replaceText('hi', MAX, 'high', 'x')]);
  s.apply([op.moveBlock('hi', MAX, null, null)]);
  s.apply([op.deleteBlock('hi', MAX)]);
  s.apply([op.updateBlock('lo', MAX - 1, content('x'))]);
  s.apply([op.updateBlock('lo', MAX, content('y'))]);
  s.apply([op.deleteBlock('lo', MAX)]);
  s.undo();
  s.undo();
  const edge = new Session('overflow-revision', { ...doc, revision: MAX });
  edge.apply([op.setTitle('cannot advance')]);
  edge.undo();
  const next = new Session('overflow-revision-minus-one', { ...doc, revision: MAX - 1 });
  next.apply([op.setTitle('last revision')]);
  next.apply([op.setTitle('beyond')]);
  next.undo();
  scenarios.push(edge.done(), next.done());
  return s.done();
}
scenarios.push(overflow());

// ---- random walks --------------------------------------------------------------------------------------------------

const WORDS = ['alpha', 'Beta', 'gamma', 'delta', 'ALPHA', 'beta', 'Épsilon', 'zeta'];
const sentence = (): string => Array.from({ length: 1 + rand(4) }, () => pick(WORDS)).join(' ');

function randomContent(allowContainer: boolean, citationIds: string[]): BlockContent {
  const kind = rand(allowContainer ? 14 : 12);
  const cite = (): { citationId?: string } => citationIds.length && chance(25) ? { citationId: pick(citationIds) } : {};
  const runs = (): { text: string; bold?: boolean; italic?: boolean; citationId?: string }[] =>
    Array.from({ length: 1 + rand(3) }, () => ({ text: `${sentence()} `, ...(chance(30) ? { bold: true } : {}), ...cite() }));
  switch (kind) {
    case 0: case 1: case 2: return { type: 'paragraph', runs: runs() };
    case 3: return { type: 'heading', level: (1 + rand(3)) as 1 | 2 | 3, text: sentence() };
    case 4: return { type: 'list', ordered: chance(50), items: Array.from({ length: 1 + rand(3) }, sentence) };
    case 5: return { type: 'quote', runs: runs(), ...(chance(50) ? { attribution: sentence() } : {}) };
    case 6: return { type: 'callout', tone: pick(['info', 'success', 'warning', 'danger', 'note'] as const), ...(chance(50) ? { title: sentence() } : {}), runs: runs() };
    case 7: return { type: 'code', language: 'ts', text: `const ${pick(WORDS).toLowerCase()} = ${rand(9)};` };
    case 8: return { type: 'divider' };
    case 9: return { type: 'table', columns: ['A', 'B'], rows: [[sentence(), sentence()]], ...(chance(50) ? { caption: sentence() } : {}) };
    case 10: return { type: 'image', url: 'https://example.com/i.png', alt: sentence(), ...(chance(50) ? { caption: sentence() } : {}) };
    case 11: return { type: 'metrics', items: [{ label: sentence(), value: String(rand(100)) }] };
    case 12: return { type: 'section', title: sentence() };
    default: return { type: 'toggle', title: sentence(), open: chance(50) };
  }
}

function walk(index: number, length: number, historyLimit?: number): Scenario {
  const s = fresh(`walk-${index}`, historyLimit === undefined ? {} : { historyLimit });
  let ids = 0;
  const newId = (): string => `w${index}-${++ids}`;
  const citationPool = ['c1', 'c2', 'c3', 'c4'];
  const live = () => s.snap.blocks;
  const containers = () => live().filter(block => block.content.type === 'section' || block.content.type === 'toggle');
  const citationIds = () => s.snap.citations.map(item => item.id);
  const anyBlock = () => live().length ? pick(live()) : undefined;
  const siblings = (parentId: string | null) => live().filter(block => block.parentId === parentId);
  const anchor = (parentId: string | null): { afterId?: string | null } => {
    const r = rand(5);
    if (r < 2) return {};
    if (r === 2) return { afterId: null };
    const sibs = siblings(parentId);
    if (r === 3 && sibs.length) return { afterId: pick(sibs).id };
    return chance(20) ? { afterId: pick(live().length ? live() : [{ id: 'ghost' }]).id } : {};
  };
  const parentChoice = (): string | null => containers().length && chance(55) ? pick(containers()).id : null;
  const newBlock = (): BlockInput => {
    const parentId = parentChoice();
    const cited = citationIds();
    const c = randomContent(true, cited);
    return { id: newId(), parentId, content: c, citationIds: cited.length && chance(30) ? [pick(cited)] : [] };
  };
  const stale = (): number => chance(10) ? 1 : 0;
  for (let step = 0; step < length; step++) {
    const kind = rand(100);
    const target = anyBlock();
    const ver = (block: { version: number }): number => block.version + stale();
    const many = (n: number) => { const picked = new Set<string>(); const out = []; for (let i = 0; i < n && live().length; i++) { const block = pick(live()); if (!picked.has(block.id)) { picked.add(block.id); out.push({ blockId: block.id, expectedVersion: ver(block) }); } } return out; };
    if (live().length > 14 && chance(50) && target) { s.apply([op.deleteBlock(target.id, target.version)]); continue; }
    if (kind < 20 || !target) { const block = newBlock(); s.apply([op.insertBlock(block, anchor(block.parentId).afterId)]); }
    else if (kind < 26) { const first = newBlock(); const batch = [first, ...Array.from({ length: rand(3) }, () => { const next = newBlock(); return chance(50) ? { ...next, parentId: first.parentId } : next; })]; s.apply([op.insertBlocks(batch, chance(30) ? null : undefined)]); }
    else if (kind < 40) s.apply([op.updateBlock(target.id, ver(target), randomContent(target.content.type === 'section' || target.content.type === 'toggle' ? false : true, citationIds()), chance(25) ? (citationIds().length ? [pick(citationIds())] : []) : undefined)]);
    else if (kind < 48) { const word = pick(WORDS); s.apply([op.replaceText(target.id, ver(target), chance(70) ? word : word.toLowerCase(), chance(20) ? '' : sentence(), { ...(chance(50) ? { all: true } : {}), ...(chance(30) ? { caseSensitive: true } : {}) })]); }
    else if (kind < 56) { const parentId = chance(40) ? null : parentChoice(); s.apply([op.moveBlock(target.id, ver(target), parentId, ...(chance(60) ? [anchor(parentId).afterId] : []) as [])]); }
    else if (kind < 60) { const group = many(2 + rand(2)); if (group.length) { const parentId = chance(40) ? null : parentChoice(); s.apply([op.moveBlocks(group, parentId, anchor(parentId).afterId)]); } }
    else if (kind < 66) s.apply([op.deleteBlock(target.id, ver(target))]);
    else if (kind < 69) { const group = many(1 + rand(3)); if (group.length) s.apply([op.deleteBlocks(group)]); }
    else if (kind < 74) {
      const subtree = [target]; for (let i = 0; i < subtree.length; i++) for (const child of live().filter(block => block.parentId === subtree[i]!.id)) subtree.push(child);
      const newIds = Object.fromEntries(subtree.map(block => [block.id, newId()]));
      if (chance(10)) delete newIds[subtree[subtree.length - 1]!.id];
      s.apply([op.duplicateBlock(target.id, ver(target), newIds, chance(30) ? anchor(target.parentId).afterId : undefined)]);
    }
    else if (kind < 78) s.apply([op.setTitle(sentence())]);
    else if (kind < 80) s.apply([op.setFormat({ page: pick(['screen', 'A4', 'letter'] as const), font: pick(['sans', 'serif', 'mono'] as const), fontSize: 10 + rand(10), lineHeight: 1 + rand(10) / 10 })]);
    else if (kind < 84) { const free = citationPool.filter(id => !citationIds().includes(id)); s.apply([op.addCitation(citation(free.length && chance(85) ? pick(free) : pick(citationPool), chance(30) ? { publishedAt: '2026-10-01T00:00:00Z' } : {}))]); }
    else if (kind < 86) s.apply([op.updateCitation(citation(pick(citationPool), { title: sentence() }))]);
    else if (kind < 88) s.apply([op.removeCitation(pick(citationPool))]);
    else if (kind < 94) { chance(50) ? s.undo(chance(10) ? s.snap.revision + 1 : undefined) : s.redo(chance(10) ? 0 : undefined); }
    else if (kind < 96) s.apply([op.updateBlock(target.id, target.version, randomContent(false, []))], { baseRevision: Math.max(0, s.snap.revision - 1 - rand(3)), conflictPolicy: 'rebase-safe' });
    else if (kind < 98) s.apply([op.replaceText(target.id, target.version, pick(WORDS), sentence(), { all: true })], { baseRevision: Math.max(0, s.snap.revision - 1 - rand(3)), conflictPolicy: 'rebase-safe' });
    else s.apply([op.setTitle(sentence()), op.deleteBlock(target.id, target.version), op.updateBlock(target.id, target.version + 1, content('after delete'))]);
  }
  return s.done();
}

const walks: Scenario[] = [];
for (let i = 0; i < 24; i++) walks.push(walk(i, 36, i % 6 === 5 ? 3 : undefined));
scenarios.push(...walks);

// ---- output --------------------------------------------------------------------------------------------------------

const steps = scenarios.flatMap(scenario => scenario.steps);
const outcomes: Record<string, number> = {};
for (const step of steps) {
  const key = `${step.action}:${step.expect.ok ? (step.expect.duplicate ? 'duplicate' : 'ok') : (step.expect.issues as { code: string }[]).map(issue => issue.code).join('+')}`;
  outcomes[key] = (outcomes[key] ?? 0) + 1;
}
const operations: Record<string, number> = {};
for (const step of steps) if (step.expect.ok && step.action === 'apply') for (const o of (step.input as Transaction).operations) operations[o.type] = (operations[o.type] ?? 0) + 1;
const file = new URL('../conformance/editor.v1.json', import.meta.url);
const note = 'Generated by scripts/export-editor-conformance.ts from the TypeScript reference. Each entry is {scenario, steps}; the scenario runs on one editor created from `initial` (historyLimit when given, else 100). A step is apply, undo or redo; `now` is the clock for that step; `input` is the transaction, or {actor, expectedRevision} for undo and redo. `expect` is the full outcome. `revisions` is getRevisions() and `final` getSnapshot() after the last step.';
// One scenario header and one step per line keeps the file reviewable and diffs readable.
const lines = scenarios.map(scenario => {
  const { steps: own, ...head } = scenario;
  return `{"scenario":${JSON.stringify(head)},"steps":[\n${own.map(step => JSON.stringify(step)).join(',\n')}\n]}`;
});
writeFileSync(file, `{"version":1,"note":${JSON.stringify(note)},"scenarios":[\n${lines.join(',\n')}\n]}\n`);
console.log(`${scenarios.length} scenarios, ${steps.length} steps`, outcomes, 'succeeded operations', operations);
